class Termometer {
  constructor(celsius) {
    this.celsius = celsius;
  }
  keFahrenheit() {
    return this.celsius * 9 / 5 + 32;
  }
  status() {
    return this.keFahrenheit() > 100 ? "Demam" : "Normal";
  }
}
const t = new Termometer(39);
console.log(t.keFahrenheit());
console.log(t.status());

