class PersegiPanjang {
  constructor(panjang, lebar) {
    this.panjang = panjang;
    this.lebar = lebar;
  }
  luas() {
    return this.panjang * this.lebar;
  }
  keliling() {
    return 2 * (this.panjang + this.lebar);
  }
}
const pp = new PersegiPanjang(5, 3);
console.log(pp.keliling());

class Kalimat {
  constructor() {
    this.kata = [];
  }
  tambah(k) {
    this.kata.push(k);
    return this;
  }
  hasil() {
    return this.kata.join(" ");
  }
}
console.log(new Kalimat().tambah("Aku").tambah("suka").tambah("JS").hasil());

