class Akun {
  constructor(username) {
    this.username = username;
    this.poin = 0;
  }
  tambahPoin(n) {
    this.poin += n;
    return this;
  }
  info() {
    return `${this.username}: ${this.poin} poin`;
  }
}
const a = new Akun("budi");
console.log(a.tambahPoin(10).tambahPoin(25).info());
